import React from 'react';
import DonorListComponent from '../components/donors/DonorList';

const DonorList = () => {
    return (
        <div>
            <DonorListComponent />
        </div>
    );
};

// Update split donors modal to refresh agents after splitting
const handleSplit = async () => {
    setSplitting(true);
    try {
        await splitDonors(agentNames);
        setShowSplitModal(false);
        setAgentNames(['']);
        
        // Show success message
        toast.success('Donors split successfully');
        
        // Refresh the donor list
        await fetchDonors();
    } catch (error) {
        toast.error(`Failed to split donors: ${error.message}`);
        console.error('Split error:', error);
    } finally {
        setSplitting(false);
    }
};

export default DonorList;
